const first = $input.first()?.json;
const video = Array.isArray(first) ? first[0] : first;

if (!video || !video.id) {
  return [{ json: { has_video: false, action: 'no_ready_video', message: 'No competitor videos with status=ready_for_pattern.' } }];
}

return [{ json: { has_video: true, video } }];

const video = $('Code: normalize ready video').item.json.video;
const first = $input.first()?.json;
const analysis = Array.isArray(first) ? first[0] : first;

if (!analysis || !analysis.id) {
  return [{ json: { ok: false, video_id: video.id, batch_id: video.batch_id, error: 'No ready competitor_video_analysis row found for this video.' } }];
}

const sourcePackage = {
  video: {
    id: video.id,
    batch_id: video.batch_id,
    platform: video.platform,
    url: video.video_url,
    caption: video.caption,
    views: video.views,
    likes: video.likes,
    comments: video.comments,
    saves: video.saves,
    shares: video.shares,
    account_average_views: video.account_average_views,
    views_multiplier: video.views_multiplier,
    engagement_rate: video.engagement_rate,
    selection_score: video.selection_score,
    selection_type: video.selection_type,
    selection_reason: video.selection_reason
  },
  analysis: {
    speech_transcript: analysis.speech_transcript || '',
    speech_segments_json: analysis.speech_segments_json || [],
    screen_text_json: analysis.screen_text_json || [],
    scene_timeline_json: analysis.scene_timeline_json || [],
    visual_summary: analysis.visual_summary || '',
    audio_bpm: analysis.audio_bpm,
    audio_energy: analysis.audio_energy,
    audio_genre: analysis.audio_genre,
    audio_drop_seconds: analysis.audio_drop_seconds,
    keyframes_storage_paths: analysis.keyframes_storage_paths || []
  }
};

const schema = {
  content_pattern: {
    hook_pattern: 'specific first 1-2 sec stop-scroll mechanism',
    visual_pattern: 'specific visual mechanism',
    scenario_pattern: 'scene/order structure',
    retention_pattern: 'why viewers continue watching',
    desire_trigger: 'status/gift/rarity/premium/attention trigger',
    proof_pattern: 'trust proof: install, hands, material, packaging, client context',
    audio_pattern: 'sound role, tempo, energy, drop, mood',
    cta_pattern: 'how action is created',
    adaptation_recipe: 'what to keep/change for premium tables without copying',
    forbidden_elements_json: [],
    caution_elements_json: [],
    pattern_score: 0,
    virality_score: 0,
    premium_score: 0,
    similarity_score: 0
  },
  recipes: [
    { recipe_type: 'close_to_competitor', title: '', first_frame_formula: '', scene_formula_json: [], screen_text_formula: '', audio_formula: '', cta_formula: '', what_to_keep_json: [], what_to_change_json: [], what_not_to_copy_json: [], usable_for_products_json: [], score: 0 },
    { recipe_type: 'more_viral', title: '', first_frame_formula: '', scene_formula_json: [], screen_text_formula: '', audio_formula: '', cta_formula: '', what_to_keep_json: [], what_to_change_json: [], what_not_to_copy_json: [], usable_for_products_json: [], score: 0 },
    { recipe_type: 'more_premium', title: '', first_frame_formula: '', scene_formula_json: [], screen_text_formula: '', audio_formula: '', cta_formula: '', what_to_keep_json: [], what_to_change_json: [], what_not_to_copy_json: [], usable_for_products_json: [], score: 0 },
    { recipe_type: 'story', title: '', first_frame_formula: '', scene_formula_json: [], screen_text_formula: '', audio_formula: '', cta_formula: '', what_to_keep_json: [], what_to_change_json: [], what_not_to_copy_json: [], usable_for_products_json: [], score: 0 }
  ]
};

const system = 'You are an elite SMM strategist for a content factory. Extract transferable viral patterns for selling premium tables. Be concrete. Return only valid JSON.';
const user = [
  'Analyze this competitor video package.',
  'Goal: maximum views, retention, virality and leads.',
  'Do not copy exact text, exact frames, logos, faces or third-party identity.',
  'If brand/logo/faces are present, keep the insight but list them as forbidden/caution and replace them in recipes.',
  'Output language for text fields: Russian.',
  'Return JSON exactly matching this shape:',
  JSON.stringify(schema),
  'SOURCE_PACKAGE:',
  JSON.stringify(sourcePackage)
].join('\n');

return [{
  json: {
    ok: true,
    video_id: video.id,
    batch_id: video.batch_id,
    analysis_id: analysis.id,
    sourcePackage,
    polza_body: {
      model: 'openai/gpt-5.2',
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.35
    }
  }
}];

const source = $('Code: build pattern prompt').item.json;
const response = $input.first()?.json || {};
const rawContent = response.choices?.[0]?.message?.content || response.message?.content || response.content || '';

function clampScore(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : fallback;
}
function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v == null || v === '') return [];
  return [v];
}
function parseJson(text) {
  if (typeof text === 'object' && text !== null) return text;
  const clean = String(text || '').trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(clean); } catch (e) {}
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(clean.slice(start, end + 1));
  throw new Error('Model did not return parseable JSON');
}

let parsed;
try {
  parsed = parseJson(rawContent || response);
} catch (error) {
  return [{
    json: {
      ok: false,
      video_id: source.video_id,
      batch_id: source.batch_id,
      error: error.message,
      raw_model_response: String(rawContent || JSON.stringify(response)).slice(0, 3000),
      update_body: { status: 'failed', updated_at: new Date().toISOString() }
    }
  }];
}

const p = parsed.content_pattern || parsed.pattern || parsed;
const now = new Date().toISOString();
const pattern = {
  competitor_video_id: source.video_id,
  batch_id: source.batch_id,
  hook_pattern: String(p.hook_pattern || ''),
  visual_pattern: String(p.visual_pattern || ''),
  scenario_pattern: String(p.scenario_pattern || ''),
  retention_pattern: String(p.retention_pattern || ''),
  desire_trigger: String(p.desire_trigger || ''),
  proof_pattern: String(p.proof_pattern || ''),
  audio_pattern: String(p.audio_pattern || ''),
  cta_pattern: String(p.cta_pattern || ''),
  adaptation_recipe: String(p.adaptation_recipe || ''),
  forbidden_elements_json: asArray(p.forbidden_elements_json),
  caution_elements_json: asArray(p.caution_elements_json),
  pattern_score: clampScore(p.pattern_score, 50),
  virality_score: clampScore(p.virality_score, 50),
  premium_score: clampScore(p.premium_score, 50),
  similarity_score: clampScore(p.similarity_score, 50),
  model_used: 'openai/gpt-5.2',
  created_at: now,
  updated_at: now
};

const allowed = new Set(['close_to_competitor', 'more_viral', 'more_premium', 'story']);
const recipes = asArray(parsed.recipes).filter(r => allowed.has(r.recipe_type)).map(r => ({
  recipe_type: r.recipe_type,
  title: String(r.title || r.recipe_type),
  first_frame_formula: String(r.first_frame_formula || ''),
  scene_formula_json: asArray(r.scene_formula_json),
  screen_text_formula: String(r.screen_text_formula || ''),
  audio_formula: String(r.audio_formula || ''),
  cta_formula: String(r.cta_formula || ''),
  what_to_keep_json: asArray(r.what_to_keep_json),
  what_to_change_json: asArray(r.what_to_change_json),
  what_not_to_copy_json: asArray(r.what_not_to_copy_json),
  usable_for_products_json: asArray(r.usable_for_products_json),
  score: clampScore(r.score, pattern.pattern_score),
  created_at: now,
  updated_at: now
}));

for (const type of allowed) {
  if (!recipes.some(r => r.recipe_type === type)) {
    recipes.push({
      recipe_type: type,
      title: type,
      first_frame_formula: pattern.hook_pattern,
      scene_formula_json: [{ step: 1, scene: pattern.scenario_pattern, purpose: 'transfer source pattern safely' }],
      screen_text_formula: pattern.hook_pattern,
      audio_formula: pattern.audio_pattern,
      cta_formula: pattern.cta_pattern,
      what_to_keep_json: [pattern.hook_pattern, pattern.retention_pattern].filter(Boolean),
      what_to_change_json: ['words', 'product', 'branding', 'exact framing'],
      what_not_to_copy_json: pattern.forbidden_elements_json,
      usable_for_products_json: ['premium tables'],
      score: pattern.pattern_score,
      created_at: now,
      updated_at: now
    });
  }
}

return [{ json: { ok: true, video_id: source.video_id, batch_id: source.batch_id, pattern, recipes, update_body: { status: 'pattern_extracted', updated_at: now } } }];

const inserted = $input.first()?.json;
const patternRow = Array.isArray(inserted) ? inserted[0] : inserted;
const parsed = $('Code: parse pattern JSON').item.json;

if (!patternRow?.id) {
  throw new Error('content_patterns insert did not return pattern id');
}

const rows = parsed.recipes.map(r => ({ ...r, content_pattern_id: patternRow.id }));
return [{ json: { video_id: parsed.video_id, batch_id: parsed.batch_id, pattern_id: patternRow.id, recipes: rows, update_body: parsed.update_body } }];
